fun square(x: Int): Int {
    return x * x
}

fun half(x: Double): Double = x / 2

fun main() {
    println(square(7))
    println(half(5.0))
}

fun describe(n: Int): String = when {
    n < 0 -> "отрицательное"
    n == 0 -> "ноль"
    else -> "положительное"
}

fun main() {
    for (i in -1..1) {
        println("$i: ${describe(i)}")
    }
}

data class Book(val title: String, val year: Int)

fun main() {
    val books = listOf(Book("Онегин", 1833), Book("Мастер", 1967))
    val old = books.filter { it.year < 1900 }
    println(old)
}
